shader.code:
// Moire Temple: a quasicrystal. Several wave gratings at evenly spaced
// angles overlap into a pattern that is symmetric but never repeats. The
// symmetry count is continuous: as it glides, the angles fan out and a new
// grating fades in, so the temple rebuilds itself. Chaos bends the straight
// waves into rings from wandering sources. The waves travel along the
// journey, so every beat pushes the whole structure a step forward.

#define TAU 6.28318531
#define PI 3.14159265

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;
  float px = 2.0 / resolution.y;

  float freq = mix(6.0, 30.0, density * density) * (1.0 + 0.2 * sin(j * 0.043));
  // Far-away sources make straight waves; nearby ones make rings.
  float reach = mix(60.0, 0.7, sqrt(chaos));
  float spin = j * 0.02;

  // Sum the gratings and their analytic gradient in one pass; the gradient
  // says how many pixels a stripe spans, for crisp but alias-free lines.
  float v = 0.0;
  float total = 0.0;
  vec2 grad = vec2(0.0);
  for (int k = 0; k < 10; k++) {
    float i = float(k);
    // Gratings past the symmetry count fade in as it rises.
    float weight = clamp(symmetry - i, 0.0, 1.0);
    if (weight <= 0.0) break;
    float a = i * PI / max(symmetry, 1.0) + spin;
    vec2 dir = vec2(cos(a), sin(a));
    vec2 wobble = chaos * 0.6 * vec2(sin(j * 0.13 + i * 2.1), cos(j * 0.11 + i * 1.3));
    vec2 d = p + dir * reach + wobble;
    float dist = length(d);
    // Alternate gratings travel in opposite directions.
    float dir2 = mod(i, 2.0) * 2.0 - 1.0;
    float phase = (dist - reach) * freq - j * 2.5 * dir2;
    v += weight * cos(phase);
    grad -= weight * sin(phase) * freq * d / dist;
    total += weight;
  }
  v /= total;
  grad /= total;

  // Op-art stripes along the contours of the interference field; their
  // count breathes along the journey.
  float lines = mix(1.5, 4.5, 0.5 + 0.5 * sin(j * 0.037));
  float s = v * lines + j * 0.05;
  float width = length(grad) * lines * px;
  float stripe = cos(s * TAU);
  float aa = TAU * width + 1e-3;
  float ink = smoothstep(-aa, aa, stripe);
  // Where stripes get thinner than a pixel, fade them to grey.
  ink = mix(ink, 0.5, smoothstep(0.25, 0.6, width));

  float hue = colour + j * 0.019;
  vec3 light = palette(hue + floor(s) * 0.11 + v * 0.15);
  vec3 dark = palette(hue + 0.5 + v * 0.3) * 0.12;
  vec3 col = mix(dark, light, ink);
  // Constructive peaks glow white-hot.
  col += smoothstep(0.55, 1.0, v) * 0.5;

  col *= 1.0 - 0.35 * smoothstep(0.6, 1.8, length(p));
  return clamp(col, 0.0, 1.0);
}
